class Aggregate(SOp):
  """Aggregate primitive."""

  def __init__(self,
               selector: Selector,
               sop: SOp,
               default: Value = 0):
    super().__init__()
    self.selector = selector
    self.sop = sop
    self.default = default
    assert isinstance(self.selector, Selector)
    assert isinstance(self.sop, SOp)

  @property
  def children(self) -> Sequence[RASPExpr]:
    return [self.selector, self.sop]


class SelectorAnd(Selector):
  """Logical AND of two selectors."""

  def __init__(self, fst: Selector, snd: Selector):
    super().__init__()
    self.fst = fst
    self.snd = snd
    assert isinstance(self.fst, Selector)
    assert isinstance(self.snd, Selector)

  @property
  def children(self) -> Sequence[RASPExpr]:
    return [self.fst, self.snd]


class SelectorOr(Selector):
  """Logical OR of two selectors."""

  def __init__(self, fst: Selector, snd: Selector):
    super().__init__()
    self.fst = fst
    self.snd = snd
    assert isinstance(self.fst, Selector)
    assert isinstance(self.snd, Selector)

  @property
  def children(self) -> Sequence[RASPExpr]:
    return [self.fst, self.snd]


class SelectorNot(Selector):
  """Logical NOT of a selector."""

  def __init__(self, inner: Selector):
    super().__init__()
    self.inner = inner
    assert isinstance(self.inner, Selector)

  @property
  def children(self) -> Sequence[RASPExpr]:
    return [self.inner]


def selector_and(fst: Selector, snd: Selector) -> Selector:
  return SelectorAnd(fst, snd)


def selector_or(fst: Selector, snd: Selector) -> Selector:
  return SelectorOr(fst, snd)


def selector_not(inner: Selector) -> Selector:
  return SelectorNot(inner)


def aggregate(selector: Selector, sop: SOp, default: Value = 0) -> SOp:
  return Aggregate(selector, sop, default=default)


