      vec = vec + self.vector_from_basis_direction(
          direction, magnitude, shape=shape)
    return vec

  def __getitem__(self, key: Iterable[BasisDirection]) -> "VectorSpaceWithBasis":
    return VectorSpaceWithBasis([d for d in self.basis_directions if d in key])

