            named_modules = dict(self.trunk.named_modules())
            if fork_module_name not in named_modules:
                raise KeyError(
                    f"fork_module {fork_module_name} not found in trunk"
                )
            fork_module = named_modules[fork_module_name]
        handle = fork_module.register_forward_hook(hook_fn)
        self.hook_handles.append(handle)
        self.head_name_to_fork_module[i] = fork_module_name

def remove_hooks(self):
    for handle in self.hook_handles:
        handle.remove()
    self.hook_handles = []

def forward(
    self, sample: Mapping, input_key: Optional[str] = None
) -> Dict:
    if input_key is None:
        input_key = getattr(sample, "input_key", None)
    self.input_key = input_key
    self.outputs = {}

    if self.input_key in self.trunk_field_args:
        args_keys = self.trunk_field_args[self.input_key]
        kwargs_keys = self.trunk_field_kwargs[self.input_key]
    elif None in self.trunk_field_args:
        args_keys = self.trunk_field_args[None]
        kwargs_keys = self.trunk_field_kwargs[None]
    else:
        raise KeyError(f"No trunk_fields specified for input_key: {self.input_key}")

    if isinstance(sample, Mapping):
        args = [sample[k] for k in args_keys]
        kwargs = {k: sample[v] for k, v in kwargs_keys.items()}
    else:
        args = [getattr(sample, k) for k in args_keys]
        kwargs = {k: getattr(sample, v) for k, v in kwargs_keys.items()}

    self.trunk(*args, **kwargs)
    outputs = copy.copy(self.outputs)
    self.outputs = {}
    self.input_key = None
    return outputs

    if self.input_key in self.trunk_field_args:
        args_fields = self.trunk_field_args[self.input_key]
        kwargs_fields = self.trunk_field_kwargs[self.input_key]
    elif None in self.trunk_field_args:
        args_fields = self.trunk_field_args[None]
        kwargs_fields = self.trunk_field_kwargs[None]
    else:
        raise KeyError(
            f"No trunk_fields specified for input_key: {self.input_key}"
        )
    return args_fields, kwargs_fields

def _get_trunk_args_kwargs(self, sample: Mapping):
    args_fields, kwargs_fields = self._get_trunk_fields()
    if self.handle_list_inputs and isinstance(sample, (list, tuple)):
        # hack: assume list of samples with same fields
        args = [
            [s[f] if f in s else None for s in sample] for f in args_fields
        ]
        kwargs = {
            k: [s[v] if v in s else None for s in sample]
            for k, v in kwargs_fields.items()
        }
    else:
        args = [sample[f] for f in args_fields]
        kwargs = {k: sample[v] for k, v in kwargs_fields.items()}
    return args, kwargs

def forward(self, inputs: Mapping):
    # inputs is a mapping from input_key to sample, or a single sample
    # containing the input_key. We support both a dict of samples and
    # a single sample when there is only one input_key in the batch.
    if isinstance(inputs, Mapping) and len(inputs) == 2 and "sample" in inputs:
        # single sample case: {"sample": sample, "input_key": key}
        # kept for backwards compatibility
        sample = inputs["sample"]
        input_key = inputs.get("input_key", None)
        return self.forward_single(sample, input_key)
    if isinstance(inputs, Mapping):
        # check if it is a single sample or a batch dict
        # if keys overlap with trunk_field_args keys, treat as batch dict
        if any(k in self.trunk_field_args for k in inputs.keys()) or (
            None not in self.trunk_field_args
            and not any(k in self.trunk_field_args for k in inputs.keys())
            and isinstance(next(iter(inputs.values()), None), Mapping)
        ):
            outputs = {}
            for input_key, sample in inputs.items():
                out = self.forward_single(sample, input_key)
                outputs.update(out)
            return outputs
        else:
            # single sample: need input_key stored in sample if possible
            # default to None which matches heads with input_key None
            input_key = inputs.get("input_key", None)
            return self.forward_single(inputs, input_key)
    return self.forward_single(inputs, None)

def forward_single(self, sample: Mapping, input_key: Optional[str]):
    self.input_key = input_key
    self.outputs = {}
    try:
        args, kwargs = self._get_trunk_args_kwargs(sample)
        self.trunk(*args, **kwargs)
        outputs = copy.copy(self.outputs)
    finally:
        self.outputs = {}
        self.input_key = None
    return outputs

def remove_hooks(self):
    for handle in self.hook_handles:
        handle.remove()
    self.hook_handles = []

